window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["anki:hematologia-gamopatias-monoclonais"]={"block":"anki:hematologia-gamopatias-monoclonais","label":"Anki · Gamopatias Monoclonais","count":64,"questions":[{"id":"anki-hematologia-gamopatias-monoclonais-16638997bb9f8378","number":"1001j","sourceNumber":"1001j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Homem de 60 anos, diabético, com quadro de fraqueza e astenia há 1 mês. Com dor progressiva de região lombar e braço direito. Na última semana apresentou constipação e confusão mental, evoluindo com sonolência há 2 dias. Foi levado pelos familiares a unidade básica de saúde onde os seguintes exames foram realizados: Hb: 8,1g/dL; Ht: 25%; Leucócitos: 7.800/mm³; Plaquetas: 160.000/mm³; VCM: 85; HCM: 30; Ureia: 88mg/dL; Creatinina: 2,0mg/dL; Albumina: 3,0g/dL; Glicose: 98mg/dL; Sódio: 135mEq/L; Cloro: 110mEq/L; Gasometria: pH/PCO₂/HCO₃; 7,20/35/18. Urina I: pH: 6,0; Densidade: 1030; Proteínas: 2+/4+; Glicose: 1+/4+; Leucócitos: 1/campo; Hemácias: 2/campo; Qual a principal hipótese diagnóstica?","options":{"A":"Mieloma múltiplo","B":"Síndrome de Sjogren","C":"Intoxicação por metformina","D":"Glomerulonefrite rapidamente progressiva"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587494","ankiGuid":"e&h9Cx^?-z"},{"id":"anki-hematologia-gamopatias-monoclonais-dbe3579731c1fd33","number":"1002j","sourceNumber":"1002j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Mulher de 76 anos apresenta emagrecimento, dor lombar, astenia e dispneia aos esforços. Desconhece comorbidades prévias, nega tabagismo etilismo ou uso de medicamentos. Ao exame, as mucosas estão descoradas; sem outras anormalidades. Exames de laboratório: Hb 7,3g/dL; LG 6.500/mm³; Plq 112.000/mm³; VHS 95mm na primeira hora; creatinina 2,2mg/dL; Ureia 47mg/dL; cálcio total 10,6g/dL; albumina serica 2,0g/dL; LDH 450Ul/L; BT 0,9mg/dL. A hematoscopia revelou o seguinte achado:\n\nConsiderando o diagnóstico mais provável para essa paciente, assinale a alternativa que apresenta o(s) exame(s) MAIS ADEQUADO(S) a ser(em) solicitado(s) nesse momento:","options":{"A":"Eletroforese de proteínas séricas e urinárias","B":"Endoscopias do trato digestivo alto e baixo","C":"Pesquisa do cromossomo Philadelphia","D":"Teste de fragilidade osmótica de eritrócitos"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":["question_bank/media/hematologia-gamopatias-monoclonais/paste-23b2ae1548dc4b1f8a322eb643a1e26c4980bcc0.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587495","ankiGuid":"zk~k=lGwOn"},{"id":"anki-hematologia-gamopatias-monoclonais-f4a66502d43ab946","number":"1003j","sourceNumber":"1003j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Um paciente com mieloma múltiplo recém diagnosticado, mas ainda virgem de tratamento, dá entrada no pronto-socorro com o seguinte quadro: rebaixamento do nível de consciência, desidratação, distensão abdominal e redução dos ruídos hidroaéreos e insuficiência renal aguda. Familiar relata que o quadro teve evolução progressiva nos últimos dias, sendo que, no início, o paciente estava apresentando diurese muito abundante, que posteriormente se reduziu, associado ao agravamento dos outros sintomas. Qual é a provável etiologia do quadro?","options":{"A":"Síndrome de lise tumoral","B":"Metástase para o sistema nervoso central","C":"Hipercalcemia","D":"Síndrome de hiperviscosidade"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587496","ankiGuid":"jfUj8O5}y0"},{"id":"anki-hematologia-gamopatias-monoclonais-04d3a42bf2564eba","number":"1004j","sourceNumber":"1004j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Qual dessas doenças não faz parte do grupo de gamopatias monoclonais?","options":{"A":"Síndrome POEMS","B":"Agamaglobulinemia ligada ao X","C":"Amiloidose de cadeias leves","D":"Macroglogulinemia de Waldenström"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587497","ankiGuid":"l]_nN6.kGO"},{"id":"anki-hematologia-gamopatias-monoclonais-10584d4627cbdfea","number":"1005j","sourceNumber":"1005j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Paciente de 68 anos, sexo feminino, procura o posto de saúde por quadro de dor lombar há 6 meses associada a fadiga e adinamia. Refere piora da dor durante o passar do dia e nega melhora com uso de anti-inflamatórios não esteroidais. Antecedente de hipertensão, dislipidemia e hipotireoidismo. Traz exames laboratoriais com Hb: 8,0 g/dL, Cr: 2,5 mg/dL, Cai 6,5 mg/dL. USG de vias urinárias com rins de tamanho preservados. Submetida a biópsia renal que evidenciou cilindros eosinofílicos. Dentre as opções abaixo, o achado mais provável no sangue periférico deste paciente é","options":{"A":"Agregados lineares de células vermelhas","B":"Reticulócitos aumentados","C":"Leucocitose com células mieloides maduras","D":"Manchas de Gumprecht"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587498","ankiGuid":"lTomG8K6Ff"},{"id":"anki-hematologia-gamopatias-monoclonais-d87b9c9e59a89ffe","number":"1006j","sourceNumber":"1006j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Homem de 65 anos procura o consultório médico referindo progressiva fadiga nos últimos 6 meses. Traz estes exames realizados há 30 dias: Hemoglobina: 9 g/dL Creatinina: 2,5 mg/dL Eletroforese de proteínas:\n\nQual o provável diagnóstico?","options":{"A":"Gamopatia monoclonal de significado incerto (MIGUS)","B":"Macroglobulinemia de Waldenstrom","C":"Mieloma múltiplo","D":"Amiloidose","E":"Sepse urinária"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":["question_bank/media/hematologia-gamopatias-monoclonais/paste-c36fcf57667520e5fd393f87ddbb0f0ace1f1085.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587499","ankiGuid":"qj[k7P%-.}"},{"id":"anki-hematologia-gamopatias-monoclonais-478f42963610c80b","number":"1007j","sourceNumber":"1007j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Homem, 71 anos de idade, com antecedente de hepatite autoimune em uso de azatioprina e prednisona, refere fadiga e dispneia aos médios esforços, sem outros sintomas. Na investigação clínica uma eletroforese de proteínas demonstrou componente monoclonal em fração de gamaglobulinas (39/dL) e a imunofixação evidenciou ser de IgG kappa. Quais exames devem ser solicitados para elucidação diagnóstica neste primeiro momento?","options":{"A":"Biópsia da medula óssea com imuno-histoquímica","B":"Hemograma, creatinina, cálcio sérico, função hepática e mielograma","C":"Elastografia hepática, biópsia hepática e de medula óssea","D":"Hemograma, albumina, B2-microglobulina e elastografia hepática"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587500","ankiGuid":"r(~L)G)p=#"},{"id":"anki-hematologia-gamopatias-monoclonais-a65e59a6c8f3f058","number":"1008j","sourceNumber":"1008j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"No mieloma múltiplo,","options":{"A":"Hipercalcemia, eventualmente observada, seria secundária à insuficiência renal aguda","B":"Sem proteinúria, não há risco para desenvolvimento de insuficiência renal aguda","C":"Há predisposição a infecções por bactérias encapsuladas devido imunodeficiência humoral predominante","D":"O principal achado do hemograma é a presença de plasmócitos"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587501","ankiGuid":"mojZeW$a+l"},{"id":"anki-hematologia-gamopatias-monoclonais-3336f8e8c87c439d","number":"1010j","sourceNumber":"1010j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Rouleaux eritrocitário, anemia, pico de gamaglobulina em eletroforese de proteínas séricas, proteinúria, o diagnóstico mais provável:","options":{"A":"Crioglobulinemia","B":"Leucemia Linfocítica Crônica","C":"Cirrose biliar primária","D":"Mieloma Múltiplo","E":"Insuficiência renal Crônica"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587503","ankiGuid":"cfjVX4-*Y."},{"id":"anki-hematologia-gamopatias-monoclonais-8caf6a0f5e0d0c79","number":"1011j","sourceNumber":"1011j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Em relação à amiloidose, analise as afirmativas a seguir: I. As manifestações podem incluir neuropatia periférica motora e sensorial, cardiomiopatia, síndrome nefrótica, síndrome de mal absorção e insuficiência hepática. II. Os sintomas e sinais, muito variados e insidiosos, podem também se manifestar através de demência, hipoacusia, tosse crônica por infecções respiratórias recorrentes acarretando diagnóstico tardio. III. Pacientes com diagnóstico de amiloidose possuem indicação de transplante de medula óssea autólogo; porém, pacientes com acometimento cardíaco grave não devem realizar o transplante de medula. Estão corretas as afirmativas","options":{"A":"I e II, apenas","B":"I e III, apenas","C":"II e III, apenas","D":"I, II e III"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587504","ankiGuid":"b2ip+MJsgE"},{"id":"anki-hematologia-gamopatias-monoclonais-9cfc04572db0f9ce","number":"1012j","sourceNumber":"1012j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Pacientes com diagnóstico de mieloma múltiplo, que apresentam depósitos no rim de proteínas com características de fibrilas amiloide do tipo AL e coradas com vermelho congo. Esses pacientes apresentam clinicamente com mais frequência:","options":{"A":"Acidose tubular renal","B":"Lesão renal aguda","C":"Doença renal crônica","D":"Síndrome nefrótica"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587505","ankiGuid":"ti/_O_P&zn"},{"id":"anki-hematologia-gamopatias-monoclonais-2c1081ef3fd98e37","number":"1013j","sourceNumber":"1013j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Paciente de 72 anos, do sexo feminino, assintomática, em exame de rotina notado com pico monoclonal de 3,8 g/dL em gamaglobulina. Apresenta creatinina sérica de 1,4 mg/dL, cálcio sérico de 8,1 mg/dL, tomografia de corpo todo de baixa intensidade normal, mielograma com infiltração plasmocitária de 18%, relação de cadeias leves livres kappa / lambda: 120. Segundo o International Myeloma Working Group, trata-se de:","options":{"A":"Síndrome de POEMS","B":"Pico monoclonal de significado indeterminado","C":"Mieloma múltiplo indolente","D":"Mieloma múltiplo ativo"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587506","ankiGuid":"]uxxx9Ve9"},{"id":"anki-hematologia-gamopatias-monoclonais-d8c35e1037ea0954","number":"1014j","sourceNumber":"1014j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Paciente, 72 anos, sexo masculino, comparece ao ambulatório de Clínica Médica com queixa de dores ósseas difusas, particularmente na coluna. Ao exame físico, apresenta-se algo hipocorado e com fácies de dor. Traz alguns exames laboratoriais: Hemoglobina 11,2g/dl (VR: 13-16 g/dl) Cálcio iônico 1,5mmol/L (VR: 1,15-1,32mmol/L) Creatinina 1,6mg/dl (VR: 0,8-1,2mg/dl) Fosfatase alcalina 64U/L (VR: 50-200U/L), além de radiografias da coluna evidenciando lesões osteolíticas difusas. LEGENDA: VR: valor de referência. Considerando a principal hipótese diagnóstica, qual dos exames a seguir deve ser solicitado?","options":{"A":"PSA total","B":"Cintilografia óssea","C":"Densitometria mineral óssea","D":"Eletroforese de proteínas séricas"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587507","ankiGuid":"xt7._kOo06"},{"id":"anki-hematologia-gamopatias-monoclonais-e55e967335899ebc","number":"1015j","sourceNumber":"1015j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Mulher de 72 anos apresenta quadro de dor em região dorsal (torácica e lombar) e em membros, especialmente em tornozelos e antebraços, há pelo menos dois meses, de caráter progressivo. Nega febre, mas refere cansaço no último mês. Apresenta-se bastante descorada ao exame físico, hidratada e anictérica. Não há baço palpável ou adenomegalias. Hb 6,5g/dL; VCM 92fL; GB 6.400 com 60% de segmentados, linfócitos 28%, plaquetas 390.000/uL. VHS 145mm na primeira hora. Creatinina 2,5mg%; ureia 65mg%; sódio 145mEq/L; potássio 4,9mEq/L. Qual dos exames é mais resolutivo quanto ao diagnóstico da paciente?","options":{"A":"Ressonância de coluna dorsal","B":"Proteinúria de Bence Jones","C":"Fator reumatoide","D":"P-ANCA e c-ANCA","E":"Eletroforese de proteínas do soro"},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587508","ankiGuid":"=V^X1VCy&"},{"id":"anki-hematologia-gamopatias-monoclonais-b96ae6762089a0d8","number":"1016j","sourceNumber":"1016j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"O acometimento ósseo pelo mieloma múltiplo - MM da doença com lesões líticas que afetam predominantemente o esqueleto do crânio, coluna e gradil costal e as áreas proximais dos membros superiores e inferiores. O item com erro é:","options":{"A":"As lesões ósseas resultam do aumento da atividade osteoblástica (reabsorção óssea, acompanhada pela exaustão da função osteoblástica e aumento da formação óssea","B":"Na avaliação radiológica inicial, quase 80% dos pacientes terão lesões líticas no esqueleto, acometendo vértebras, arcos costais, crânio, ombros, pelve e ossos longos","C":"Quase 10% dos doentes têm osteopenia difusa ou osteoporose ao diagnóstico","D":"Apesar de geralmente diagnosticadas em radiografias, as lesões líticas só aparecem quando já se perdeu acima de 30% do trabeculado ósseo"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587509","ankiGuid":"O<$%,}2D]#"},{"id":"anki-hematologia-gamopatias-monoclonais-b9249b4c83275a50","number":"1017j","sourceNumber":"1017j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Homem, 67 anos, iniciou investigação de anemia normocítica e normocômica e redução da taxa de filtração glomerular, detectadas em exame de rotina. Comparece à consulta com o seguinte gráfico de eletroforese de proteínas:\n\nQual distúrbio hidroeletrolítico está associado à doença em questão?","options":{"A":"Hipopotassemia","B":"Hipercalcemia","C":"Hiponatremia","D":"Hipernatremia","E":"Hipocalcemia"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":["question_bank/media/hematologia-gamopatias-monoclonais/paste-43e15ab00bc73862411b65dce0b45c5757da88ae.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587510","ankiGuid":"ia<O3eA&8]"},{"id":"anki-hematologia-gamopatias-monoclonais-1a110fd3cc7f25e8","number":"1018j","sourceNumber":"1018j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Paciente, 71 anos, masculino, deu entrada no PA com queda do quadro geral, desidratação, aumento das escórias nitrogenadas, anemia normocítica e normocrômica. Raio X do tórax evidenciou múltiplas lesões líticas nos arcos costais. Aventou-se a hipótese de mieloma múltiplo. Qual o principal distúrbio eletrolítico encontrado nessa patologia?","options":{"A":"Hipernatremia","B":"Hipocalemia","C":"Hipercalemia","D":"Hipocalcemia","E":"Hipercalcemia"},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587511","ankiGuid":"jUj_na.Q`("},{"id":"anki-hematologia-gamopatias-monoclonais-dc1185bb4665f67d","number":"1019j","sourceNumber":"1019j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Homem com 50 anos de idade relata que há 6 meses tem dor lombar de forte intensidade com diversas idas ao pronto-socorro, sendo medicado com anti-inflamatórios (AINH), com alívio parcial. Trouxe os seguintes exames: HB: 9,2 g/dL; Ht: 28%; VCM: 86 fL; HCM 32 pg. Leucócitos: 4.500/mm3 e plaquetas 250.000/mm3. Cr: 2,5 mg/dL; ureia: 85 mg/dL; TGO: 32 e TGP: 35. RX de coluna lombar com fraturas de acunhamento de L2 e L3. O diagnóstico mais provável e exames prudentes para investigação são, respectivamente:","options":{"A":"Anemia ferropriva pelo uso de AINH; perfil de ferro e endoscopia","B":"Anemia de doença crônica por insuficiência renal associado ao uso de anti-inflamatórios; perfil de ferro","C":"Mieloma múltiplo; eletroforese de proteínas séricas e urinárias e avaliação da medula óssea","D":"Mieloma múltiplo; proteinúria de Bence-Jones e cintilografia óssea"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587512","ankiGuid":"MWiN_[7%X}"},{"id":"anki-hematologia-gamopatias-monoclonais-ba8d0b1c84fa01fc","number":"1020j","sourceNumber":"1020j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Idosa, 78 anos, durante avaliação por geriatra teve exame mostrando elevação de cálcio e anemia. O profissional prosseguiu com investigação e encontrou em radiografias de pelve alterações ósseas compatíveis com lesões líticas e na imunoeletroforese evidenciou monoclonalidade IgG-kappa.\n\nSobre o diagnóstico provável pode-se inferir que:","options":{"A":"O achado de plasmocitose em medula óssea confirma o diagnóstico de mieloma múltiplo","B":"Os exames sugerem câncer de ovário avançado e a próxima intervenção deve ser a laparotomia","C":"A idosa é portadora de gamopatia monoclonal de significado indeterminado","D":"Trata-se de caso grave de osteoporose e é necessária urgentemente a intervenção com bisfosfonato"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":["question_bank/media/hematologia-gamopatias-monoclonais/paste-0e52e3e821e29d9bb21fa8d24538473035457000.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587513","ankiGuid":"B5![8?y3~W"},{"id":"anki-hematologia-gamopatias-monoclonais-f3e65133d8a72df3","number":"1021j","sourceNumber":"1021j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Homem de 70 anos, com história de dor lombar progressiva com piora à movimentação, associada a emagrecimento, apresenta Lasegue positivo à direita, astenia e fraqueza de início há dois meses. Os exames mostram hemoglobina = 9g/dL, leucócitos = 9.000/mm³, diferencial normal, plaquetas = 200.000/mm³, glicose = 90mg/dL, creatinina = 1,1mg/dL, proteína total = 7,5g/dL, albumina = 3,0g/dL, VHS = 110mm/hora, ácido úrico = 7,5mg/dL, fosfatase alcalina = 120U/L, cálcio = 10,5mg/dL e fósforo = 3,5mg/dL. O exame de imagem da coluna revela intensa osteopenia sem lesões líticas e PSA = 9,5ng/mL. O paciente é tabagista de 40 maços-ano e etilista social. A hipótese diagnóstica principal é de:","options":{"A":"Mieloma múltiplo","B":"Tumor de próstata metastático","C":"Osteoporose secundária a hipogonadismo","D":"Metástases na coluna por tumor epidermoide de pulmão"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587514","ankiGuid":"B(2h+J=BM4"},{"id":"anki-hematologia-gamopatias-monoclonais-9c2ec1b0902ab7e7","number":"1022j","sourceNumber":"1022j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"A macroglobulinemia de Waldenström está associada à síndrome de hiperviscosidade. Os principais componentes da síndrome são","options":{"A":"Turvação visual, cefaleia e parestesias","B":"Vômitos, náuseas e icterícia","C":"Diarreia, palpitação e tonteira","D":"Hipofonese de bulhas, hipotensão e bradicardia","E":"Hipertensão, bradicardia e alterações do ritmo respiratório"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587515","ankiGuid":"w%6kg4},z~"},{"id":"anki-hematologia-gamopatias-monoclonais-7215d139785563c0","number":"1023j","sourceNumber":"1023j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"No mieloma múltiplo - MM, plasmócitos monoclonais geralmente representam mais de 10% das células nucleadas da medula óssea; no entanto 4% dos pacientes com MM sintomático têm plasmocitose abaixo de 10%. Não podemos aceitar que:","options":{"A":"Isto pode ser consequência da infiltração focal por células do MM ou de problema de coleta da medula óssea, principalmente quando realizado apenas mielograma","B":"A infiltração corresponde a 50% em média","C":"Se houver proteína-M elevada (maior que 5g/dL) ou sintomas sugestivos de hiperviscosidade, não é recomendável a medida da viscosidade sérica","D":"Deve-se repetir a coleta em local, preferivelmente com biópsia de medula óssea (BMO)"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587516","ankiGuid":"lJ]biE$Xlr"},{"id":"anki-hematologia-gamopatias-monoclonais-cef2521b0b44d728","number":"1024j","sourceNumber":"1024j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"A identificação da doença mieloma múltiplo - MM em seu estágio inicial e o encaminhamento ágil e adequado para o atendimento especializado dão à Atenção Básica um caráter essencial para um melhor resultado terapêutico e prognóstico dos casos. A maioria dos pacientes apresenta-se com sinais e sintomas de infiltração plasmocitária (óssea ou de outros órgãos) ou lesão renal por deposição de proteína monoclonal tumoral. As manifestações clínicas mais comuns ao diagnóstico são listadas abaixo, qual dos itens apresenta erro?","options":{"A":"Doença óssea - Dor óssea principalmente em tórax e coluna induzida pela movimentação (60%)","B":"Doença óssea evoluindo com déficit motor ou sensitivo, fraturas patológicas, redução da altura","C":"Insuficiência renal - Edema, oligúria, uremia, elevação de creatinina (48%)","D":"A insuficiência renal é secundária principalmente à nefropatia obstrutiva devido a cilindros de cadeia pesada monoclonal (proteína de Bence Jones) que se depositam nos túbulos contornados distais e coletores, conhecida como “rim do mieloma”, e à hipocalcemia"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587517","ankiGuid":"I^[F57i;^N"},{"id":"anki-hematologia-gamopatias-monoclonais-ca5813d9c6d432a6","number":"1025j","sourceNumber":"1025j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Paciente de 80 anos, sexo masculino, comparece a unidade básica de saúde com queixa de lombalgia, que piora ao movimento, iniciada há cerca de 2 meses. Informa diagnóstico recente de anemia. Não está em uso de medicações. Trouxe resultado de exames solicitados há uma semana: Hemoglobina = 10,2 g/dL (VR: 11.3 a 16.3); VCM = 85 FL (VR: 77 a 92); HCM = 30 pg (VR: 27 a 32); Global de leucócitos = 6200/ml (VR = 4.000 a 10.000/ml); Neutrófilos = 50% (VR: 45 a 75%); Linfócitos = 35 % (VR = 22 a 40%); Monócitos = 9% (VR: 3 a 10%); Eosinófilos = 5% (VR: 1 a 5%); Basófilos = 1% (VR: 0 a 2%); Plaquetas: 150.000/ml (VR: 130.000 a 370.000/ml); Reticulócitos = 0,4% (VR: 0,5 a 2,17%); Ferro sérico = 80 mcg/dl (VR: 60 a 160); Ferritina = 150 (VR: 13 a 200 ng/ml); Capacidade total de ligação do ferro (TIBIC) = 300 mcg/dl (VR: 240 a 410); Creatinina = 2,6 mg/dL ( VR: 0,6-1,2 mg/dL) e uréia = 50 mg/dL (VR: 16-40 mg/dL). Albumina 3,6 g/dL (VR: 3,5-4,7 g/dL); Cálcio total = 13,2 (VR: 8,5-10,2 mg/dL). Assinale a alternativa que contém o diagnóstico mais provável:","options":{"A":"Hiperparatireoidismo primário","B":"Mieloma múltiplo","C":"Artrite reumatoide","D":"Osteoartrose"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587518","ankiGuid":"Hi]Fwck.Pj"},{"id":"anki-hematologia-gamopatias-monoclonais-12ece0981fe29069","number":"1026j","sourceNumber":"1026j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Homem de 65 anos, diagnóstico prévio de insuficiência cardíaca congestiva (fração de ejeção: 35%), internada devido perda de peso (10 kg/6 meses), anemia e dor lombar. Apresenta os seguintes exames: Hb: 8g/dL, hematócrito: 24 %, Cr: 3 mg/dL, Ur: 100 mg/dL, AST: 45 U/L, ALT: 38 U/L. À radiografia de coluna lombar: osteopenia difusa e fraturas parciais de L3 e L4 por encunhamento. Após 3 dias de internação, teve dor abdominal importante e anúria, laboratório com cálcio total: 17 mg/dL e albumina: 3,2 g/dL. Sobre o caso clínico, assinale a alternativa CORRETA:","options":{"A":"Eletroforese de proteínas séricas e urinárias, mielograma e biópsia de medula óssea podem ajudar a esclarecer o diagnóstico hematológico","B":"A conduta mais adequada para a hipercalcemia deste paciente é a hidratação vigorosa","C":"8% de plasmócitos na medula óssea confirma a principal hipótese diagnóstica","D":"A etiologia mais provável da hipercalcemia em questão é o uso de diurético tiazídico"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587519","ankiGuid":"d+$(0laf&A"},{"id":"anki-hematologia-gamopatias-monoclonais-6161c9001d5cf33f","number":"1027j","sourceNumber":"1027j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Um paciente de 75 anos de idade procurou atendimento por diminuição do volume urinário e intolerância aos esforços, associada a dor torácica ventilatório-dependente e a dor lombar de forte intensidade. Realizou exames de laboratório, que evidenciaram: hemoglobina = 8,6 g/dL, hematócrito = 25%, leucócitos = 6.600/mm3, sem particularidades no diferencial, plaquetas = 190 mil/mm3, creatinina = 4,51 mg/dL, potássio = 6,3 mEq/L, cálcio sérico corrigido = 13 mg/dL, ureia = 109 mg/dL, reserva alcalina = 12 U/L. Ao exame físico, o paciente encontrava-se em regular estado geral, hipocorado, com presença de sopro sistodiastólico 2+/4+, murmúrio vesicular reduzido em 1/3 inferior direito, edema em membros inferiores 3+/4+, abdome sem particularidades e percussão-punho-lombar (PPL) negativo, PA = 180 mmHg X 90 mmHg, FC = 97 bpm, SatO2 = 92% em ar ambiente. Considerando esse caso clínico e os conhecimentos médicos correlatos, julgue o item a seguir. A lombalgia, nesse paciente, provavelmente se deve a lesões ósseas de características líticas, associadas à hipótese diagnóstica principal.","options":{"A":"Certo","B":"Errado"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587520","ankiGuid":"p]nnp55a:S"},{"id":"anki-hematologia-gamopatias-monoclonais-a4d6b7644608a044","number":"1028j","sourceNumber":"1028j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Homem, 61 anos de idade, apresenta em exame de rotina eletroforese de proteínas com componente monoclonal em fração de gamaglobulinas (4g/dL). Ele refere cansaço e nega outros sintomas. Quais exames você solicitaria para elucidação diagnóstica?","options":{"A":"Biópsia da medula óssea com citometria de fluxo do sangue periférico","B":"Hemograma, creatinina, cálcio sérico, avaliação esquelética por raio X","C":"Ressonância nuclear magnética da coluna vertebral com biópsia dirigida","D":"Albumina e β2-microglobulina séricas","E":"Eletroforese de hemoglobina com quantificação de cadeias leves"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587521","ankiGuid":"EIFf!KVHFu"},{"id":"anki-hematologia-gamopatias-monoclonais-b4aa6eea98e2c034","number":"1029j","sourceNumber":"1029j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Paciente do sexo masculino de 67 anos, caucasiano, sem patologias prévias conhecidas, se apresenta na consulta ambulatorial com queixa de fraqueza há 2 meses, trazendo consigo exames realizados há 1 semana atrás pela Unidade Básica de Saúde. O laboratório mostra anemia grave (hemoglobina de 5 g/dl), classificada como normocítica e normocrômica, associado à insuficiência renal (creatinina de 3,2 mg/dl). A esposa que o acompanha também refere que há 2 dias apresenta confusão mental. Assinale a alternativa correta:","options":{"A":"O paciente é portador de insuficiência renal crônica e deve receber o tratamento adequado com IECA, bicarbonato e eritropoietina; o episódio de confusão pode ser justificado por uma provável uremia","B":"O paciente apresenta uma anemia aguda, sendo imperativo a pesquisa de sangramento gastrointestinal e o interrogatório pelo uso de anti-inflamatórios","C":"O paciente apresenta uma anemia desproporcional ao grau de insuficiência renal, devendo ser considerada a possibilidade de patologias concomitantes, como por exemplo, mieloma múltiplo. A confusão mental pode ser hipercalcemia","D":"O paciente tem uma neoplasia de sítio indeterminado, sendo o adenocarcinoma de próstata uma possibilidade, assim como a etiologia da insuficiência renal ser pós-renal"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587522","ankiGuid":"nV7*.Y-jy."},{"id":"anki-hematologia-gamopatias-monoclonais-cfd2be58c688b9ad","number":"1030j","sourceNumber":"1030j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Mulher de 63 anos, diagnosticada há 15 dias com mieloma múltiplo. Qual afirmativa abaixo está correta:","options":{"A":"A ocorrência de hipercalcemia, eventualmente observada, é secundária à insuficiência renal aguda","B":"Na ausência de proteinúria, não há risco para desenvolvimento de insuficiência renal aguda","C":"Existe predisposição a infecções por bactérias encapsuladas devido imunodeficiência humoral predominante nesses casos","D":"O achado do hemograma mais significativo é a presença de plasmócitos"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587523","ankiGuid":"M(m6Ki,q+U"},{"id":"anki-hematologia-gamopatias-monoclonais-b3f01831c72e692d","number":"1031j","sourceNumber":"1031j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Foi admitida em enfermaria uma senhora de 63 anos de idade com história de fraqueza, perda ponderal e dor óssea. Nos exames da admissão foi comprovada anemia, lesões líticas em quadril e fêmur além de eletroforese de proteína ter evidenciado pico monoclonal, cuja avaliação de imunoglobulinas demonstrou ser IgG kappa. Concluído o diagnóstico de mieloma múltiplo foi transferida aos cuidados da equipe da hematologia para tratamento específico. Sobre a patologia citada é CORRETO afirmar que:","options":{"A":"O mieloma múltiplo é uma neoplasia maligna de linfócitos B localizados nos linfonodos, mais precisamente em centros germinativos, e após disseminação sistêmica levam ao surgimento de lesões líticas","B":"O mieloma múltiplo faz parte do grupo das discrasias de plasmócitos que compreende ainda a gamopatia monoclonal de significado incerto, mieloma múltiplo indolente (smoldering), leucemia de células plasmáticas e alguns casos de amiloidose","C":"A presença de pico monoclonal é exclusiva às neoplasias plasmocitárias","D":"A doença óssea do mieloma múltiplo sempre se caracteriza por lesões líticas e devem ser tratadas somente se há hipercalcemia e/ou fratura patológica"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587524","ankiGuid":"Hn,_./8y^^"},{"id":"anki-hematologia-gamopatias-monoclonais-deccf618a6de281b","number":"1032j","sourceNumber":"1032j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Homem, 59 anos, atleta, sem comorbidades, admitido em emergência com história de dores ósseas há cerca de 2 meses, fadiga intensa de início há cerca de 5 dias, com singultos associados a náusea e vômitos. Nega febre. Em laboratório da admissão, encontra-se: Cr = 3,3; U = 177; K = 6,1; Ca = 14; Mg = 2,0. EAS sem proteinúria. Urina 24h com proteinúria 3,2 g. Qual o diagnóstico mais provável?","options":{"A":"Rabdomiólise","B":"Síndrome hemolítico-urêmica","C":"Mieloma múltiplo","D":"Crioglobulinemia","E":"Leptospirose"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587525","ankiGuid":"oWflgue0~<"},{"id":"anki-hematologia-gamopatias-monoclonais-ab78934779d55b0e","number":"1033j","sourceNumber":"1033j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Homem de 68 anos vem progressivamente apresentando cansaço, fraqueza e dor no corpo. Foi à emergência com dor lombar forte e realizou tomografia de abdômen e pelve com contraste venoso, que mostrou colapso da primeira vértebra lombar. O hemograma mostrou anemia normocrômica e normocítica, Hb = 10,0g/dL, plaquetas = 100.000 e função renal normal. Dias depois, evoluiu com oligúria. Está hipocorado e com fácies de dor, tem linfonodos de menos de 1cm, cervicais, elásticos, móveis e indolores, sem visceromegalias. Novos exames mostram: Hb = 9,6g/dL, normocromia e normocitose, com formação de fenômeno de Roleaux, plaquetas = 99.000, VHS = 110mm/h, sódio = 136mEq/L, potássio = 3,8mEq/L, creatinina = 3,6mg/dL, cálcio total = 13,2mg/dL, proteínas totais = 9,2g/dL, sendo 3,4g/dL de albumina e ácido úrico = 10mg/dL. Antes de solicitar outros exames, esse quadro levanta a suspeita principal de:","options":{"A":"Púrpura trombocitopênica trombótica","B":"Linfoma de células do manto","C":"Leucemia mieloide crônica","D":"Mieloma múltiplo"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587526","ankiGuid":"[~+ch2zGz"},{"id":"anki-hematologia-gamopatias-monoclonais-8463e41e61278868","number":"1034j","sourceNumber":"1034j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"No mieloma múltiplo:","options":{"A":"Hipercalcemia, eventualmente observada, seria secundária à insuficiência renal aguda","B":"Sem proteinúria, não há risco para desenvolvimento de insuficiência renal aguda","C":"Há predisposição a infecções por bactérias encapsuladas devido à imunodeficiência humoral predominante","D":"O principal achado do hemograma é a presença de plasmócitos"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587527","ankiGuid":"LzbD+Yb:Oa"},{"id":"anki-hematologia-gamopatias-monoclonais-9d20520591f3e149","number":"1035j","sourceNumber":"1035j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Homem, 49 anos, hipertenso sem tratamento, refere redução do volume urinário, mal estar geral e prostração há 1 semana. Sem outras queixas. Exame físico = BEG, hipocorado 2+/4, anictérico. Murmúrio vesicular reduzido e presença de estertores crepitantes em bases bilateralmente. RCR em 2 T, sem sopros PA: 152x98 mmHg. FC: 96 bpm. Exames laboratoriais = creatinina: 4,1 mg/dL; ureia: 104 mg/dL; sódio: 141 mEq/L; potássio: 5,4 mEq/L; cálcio total: 12 mg/dL (VN: 8,4-10,5); Hb: 8,1; Ht: 24%; VCM: 92 fL; HCM: 31,8 pg; RDW 13,5%, GB: 4,900/µL, plaquetas: 118 x 10³/ µL. Reticulócitos: 22.000/µL (VN: 35.000-100.000); Urina 1: densidade 1015, proteínas 4+, nitrito negativo, leucócitos 2/campo, hemácias 3/campo.\n\nQual é a alteração compatível com o diagnóstico mais provável?","options":{"A":"Figura I","B":"Figura II","C":"Figura III","D":"Figura IV"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":["question_bank/media/hematologia-gamopatias-monoclonais/paste-addfe96678cfae0ed6b62cfd526c73cde2a79b7d.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587528","ankiGuid":"bahTgouGNU"},{"id":"anki-hematologia-gamopatias-monoclonais-92d9ac3a2692932f","number":"1036j","sourceNumber":"1036j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Homem de 69 anos de idade, diabético há 20 anos em uso de metformina e glibenclamida (ambos em dose máxima) vem ao ambulatório de clínica médica com queixa de lombalgia à direita, há 2 meses. No período, desenvolveu fraqueza generalizada e dispneia aos grandes esforços. Nega outros antecedentes mórbidos relevantes. No exame clínico, pressão arterial = 136 x 52 mmHg; pulso = 96 bpm; descorado ++/4+. Dor leve à palpação de região lombar direita. Sem outras alterações semiológicas. Realizou os seguintes exames:\n\nQual alternativa apresenta a principal hipótese diagnóstica para o caso e o distúrbio hidroeletrolítico mais comumente associado a essa hipótese diagnóstica?","options":{"A":"Mieloma múltiplo e hipopotassemia","B":"Nefropatia diabética e hipercalcemia","C":"Nefropatia diabética e hipopotassemia","D":"Mieloma múltiplo e hipercalcemia"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":["question_bank/media/hematologia-gamopatias-monoclonais/paste-ec524390e0a4763d30447d5e47aa91a84a16d981.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587529","ankiGuid":"v`Fz89VmYz"},{"id":"anki-hematologia-gamopatias-monoclonais-a35cb5a31f1bb515","number":"1037j","sourceNumber":"1037j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Homem, 68 anos, em investigação de anemia acompanhada de perda de função renal, realiza, entre outros exames, um proteinograma sérico, cujo traçado é:\n\nEm relação aos dados, afirma-se:\nI - Os dados do proteinograma levam à indicação de um proteinograma urinário;\nII - O proteinograma mostra gamopatia policlonal, fazendo pensar em doença autoimune;\nIII - O proteinograma descarta mieloma múltiplo por não apresentar pico monoclonal.\n\nEstá/Estão correta(s) a(s) afirmativa(s)","options":{"A":"I, apenas","B":"II, apenas","C":"III, apenas","D":"I e III, apenas","E":"I, II, III"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":["question_bank/media/hematologia-gamopatias-monoclonais/paste-aab3213caf1bfa3673db9800b78103c3d1fc69ea.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587530","ankiGuid":"tuD:`=&N|P"},{"id":"anki-hematologia-gamopatias-monoclonais-9d65786e23cf1d8c","number":"1038j","sourceNumber":"1038j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Idoso de 64 anos, afrodescendente, está internado devido a dores ósseas, anemia (hemoglobina = 9,3g/dL), hipercalcemia (cálcio sérico = 11,2mg/dL) e retenção leve de escórias nitrogenadas (creatinina = 2,1mg/dL). Radiografias de esqueleto revelam múltiplas lesões líticas no crânio e na bacia. O resultado de exame complementar que corrobora a principal hipótese diagnóstica para o caso é:","options":{"A":"Ultrassonografia da tireoide com nódulo único e grande, com sinal do halo","B":"Hiperglobulinemia monoclonal na eletroforese de proteínas","C":"Produto cálcio x fósforo superior a 65 no sangue periférico","D":"Aspirado de medula óssea rico em eosinófilos"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587531","ankiGuid":"OV9gln}{0,"},{"id":"anki-hematologia-gamopatias-monoclonais-f387f0c652b37618","number":"1039j","sourceNumber":"1039j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Homem afro-americano, 64 anos de idade, é avaliado no hospital para insuficiência cardíaca congestiva, insuficiência renal e polineuropatia. O exame físico foi notável em razão desses achados e de pápulas serosas salientes na axila e na região inguinal. O laboratório demonstrou uréia de 60mg/dL e uma creatinina de 6,3 mg/dL. A proteína total era de 9,0g/dL, com albumina de 3,2g/dL. Hematócrito era de 24% e a contagem de leucócitos e de plaquetas estava normal. O exame de urina revelou 3+ de proteinúria, mas não apresentou cilindros celulares. Avaliação adicional incluiu um ecocardiograma com ventrículo esquerdo hipertrofiado e função sistólica preservada. Qual dos testes a seguir tem maior probabilidade de diagnosticar a doença oculta?","options":{"A":"Biópsia da medula óssea","B":"Eletromiograma (EMG), com estudos de condução nervosa","C":"Biópsia de tecido adiposo","D":"Cateterização do coração direito","E":"Ultrassonografia renal"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587532","ankiGuid":"O0y1c[^]P_"},{"id":"anki-hematologia-gamopatias-monoclonais-8fc1b8cca6127d67","number":"1040j","sourceNumber":"1040j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Medida terapêutica inadequada para o paciente com disfunção renal secundária ao mieloma múltiplo:","options":{"A":"Quimioterapia para redução da proteína monoclonal","B":"Inibição da ciclooxigenase-2","C":"Tratar a hipercalcemia","D":"Evitar exames radiológicos com contrastes","E":"Bortexomibe"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587533","ankiGuid":"v:Gw{;#i;"},{"id":"anki-hematologia-gamopatias-monoclonais-4763e8a6ea729708","number":"1041j","sourceNumber":"1041j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Paciente do sexo masculino, de 78 anos, completamente assintomático, com diagnóstico de mieloma múltiplo, com hemoglobina de 14 g/dL, leucócitos de 9.000/uL, plaquetas de 160.000/uL, cálcio iônico normal, creatinina de 1,0, inventário ósseo normal, mielograma com 66% de plasmócitos, relação de cadeias Kappa/Lambda (Free Light Chain) de 120,0, proteína M de 4,0 g/dL. Segundo o International Myeloma Working Group, qual é a conduta indicada?","options":{"A":"Ressonância magnética para completar estadiamento","B":"Corticoterapia isolada","C":"Observação e seguimento","D":"Quimioterapia tripla"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587534","ankiGuid":"b{}):kCdOK"},{"id":"anki-hematologia-gamopatias-monoclonais-b903b178190cf630","number":"1042j","sourceNumber":"1042j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Paciente com proteína monoclonal sérica \"maior ou igual a\" 3 g/dl e/ou células plasmáticas na medula óssea maior ou igual a 10% e ausência de anemia, insuficiência renal, hipercalcemia e lesões ósseas líticas. O diagnóstico mais provável dessa condição é:","options":{"A":"Gamopatia monoclonal de significado indeterminado","B":"Mieloma múltiplo indolente","C":"Mieloma múltiplo","D":"Leucemia de células plasmáticas"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587535","ankiGuid":"cU^tq;UX;-"},{"id":"anki-hematologia-gamopatias-monoclonais-44db18d41644130f","number":"1043j","sourceNumber":"1043j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Homem de 64 anos vem encaminhado do ambulatório de ortopedia após fratura patológica por compressão de corpos vertebrais. Apresenta radiografia de ossos longos e crânio com imagens de lesões líticas. Exames laboratoriais: Hb:10 g/dl; Ht: 30%; VCM: 100 fl; GB: 3500/mm³; Plaq: 250.000/mm³; ureia: 90 mg/dl; creatinina: 2,1 mg/dl; Cálcio: 11 mg/dl. Qual é a hipótese diagnóstica e o exame laboratorial fundamental para o diagnóstico?","options":{"A":"Osteoporose, densitometria óssea","B":"Plasmocitoma solitário, biópsia da lesão lítica","C":"Mieloma múltiplo, biópsia de medula óssea","D":"Tumor primário ósseo, cintilografia","E":"Anemia falciforme, eletroforese de hemoglobina"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587536","ankiGuid":"nv{Q>KWh<#"},{"id":"anki-hematologia-gamopatias-monoclonais-f1dae6077ef9390b","number":"1044j","sourceNumber":"1044j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Sobre a amiloidose sistêmica primária, pode-se afirmar que:","options":{"A":"Os rins raramente são afetados","B":"Macroglossia, equimose periorbitária e distrofia das unhas constituem sinais clínicos da amiloidose AL","C":"O acometimento cardíaco pode ocasionar miocardiopatia dilatada","D":"A macroglossia é patognomônica e está presente em mais de 90% dos pacientes","E":"Em geral a amiloidose AL é insidiosa e de curso indolente"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587537","ankiGuid":"y3#e5!LH5^"},{"id":"anki-hematologia-gamopatias-monoclonais-711ac8caa8946fd4","number":"1045j","sourceNumber":"1045j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"A macroglobulinemia de Waldenström é uma neoplasia linfoplasmocitária que secreta caracteristicamente qual imunoglobulina?","options":{"A":"IgA","B":"IgD","C":"IgE","D":"IgG","E":"IgM"},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587538","ankiGuid":"MXSh74~a1v"},{"id":"anki-hematologia-gamopatias-monoclonais-0edc62ba31d0227d","number":"1046j","sourceNumber":"1046j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Paciente de 75 anos com queixa de anemia e dor costal à direita. Radiografia de costelas, crânio e coluna lombar evidenciando lesões líticas. Eletroforese de proteínas com pico monoclonal. Considerando o diagnóstico mais provável, assinale a alternativa CORRETA:","options":{"A":"A dor decorrente da infiltração óssea piora principalmente à noite e deve ser tratada inicialmente com uso de anti-inflamatórios","B":"A proteinúria apresentada pelo paciente é à custa de cadeias leves e não de albuminúria","C":"A hipergamaglobulinemia confere aos pacientes um aumento da resistência a infecções bacterianas e germes encapsulados","D":"A fosfatase alcalina é usualmente normal, mesmo com lesões ósseas extensas, por não haver atividade osteoblástica"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587539","ankiGuid":"tSic7m1L,7"},{"id":"anki-hematologia-gamopatias-monoclonais-6f5f8cb98efae0f8","number":"1047j","sourceNumber":"1047j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"A associação de anemia, hipercalcemia, insuficiência renal e fraturas patológicas são características de:","options":{"A":"Deficiência de vitamina D","B":"Mieloma múltiplo","C":"Linfoma de Hodgkin","D":"Melanoma"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587540","ankiGuid":"eg-8Gg2uCK"},{"id":"anki-hematologia-gamopatias-monoclonais-618da6fa5e687645","number":"1048j","sourceNumber":"1048j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Paciente 72 anos, masculino, tem anemia, insuficiência renal, hipercalcemia e lesões ósseas líticas, com presença de proteína monoclonal por imunofixação. Qual deve ser o diagnóstico?","options":{"A":"Adenocarcinoma de próstata metastático","B":"Mieloma múltiplo","C":"Adenocarcinoma de pulmão metastático","D":"Neoplasia maligna de rim metastática","E":"Tumor de paratireoide metastático"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587541","ankiGuid":"J#=`$d,[wP"},{"id":"anki-hematologia-gamopatias-monoclonais-e505e99410b6ec8f","number":"1049j","sourceNumber":"1049j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Em relação ao Mieloma Múltiplo (MM), assinale a alternativa CORRETA:","options":{"A":"É uma neoplasia benigna, de origem hematopoiética, caracterizada pela proliferação clonal de plasmócitos na medula óssea, que, na maioria dos casos, secretam proteína monoclonal detectável no sangue ou urina","B":"Corresponde a aproximadamente 0,2% dos tumores malignos e a até 5% das neoplasias hematológicas","C":"É mais frequente em mulheres do que em homens, e em brancos (caucasianos) do que em negros","D":"Mais de 90% dos casos ocorrem após os 50 anos, com pico de incidência no ocidente entre 60 e 70 anos de idade","E":"No Brasil, a doença ocorre mais tardiamente (a idade mediana dos pacientes ao diagnóstico é de 80 anos)"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587542","ankiGuid":"vOUw?r;3F("},{"id":"anki-hematologia-gamopatias-monoclonais-bf41dab744aa4171","number":"1050j","sourceNumber":"1050j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Considere as imagens abaixo:\n\nAs imagens que pertencem ao mesmo paciente são, com maior probabilidade:","options":{"A":"II, III e V","B":"I, IV e VI","C":"II, IV e V","D":"I, III e VI","E":"II, III e VI"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":["question_bank/media/hematologia-gamopatias-monoclonais/paste-166baaa7bb9e1a1b4ee7a639e49f2512f896b894.png","question_bank/media/hematologia-gamopatias-monoclonais/paste-6b49442745ca98ce3a266fe335444e962cc71266.png","question_bank/media/hematologia-gamopatias-monoclonais/paste-76832903ffd83e61c9c1cf8fa095f90eded86dbe.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587543","ankiGuid":"Eh(M20r0TQ"},{"id":"anki-hematologia-gamopatias-monoclonais-60c44b1879dea6cc","number":"1051j","sourceNumber":"1051j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Um paciente de 72 anos, assintomático, vai a uma consulta de rotina com seu Cardiologista, que solicita, dentre outros exames, uma eletroforese de proteínas; esta, revela um aumento da fração gama com aspecto monoclonal. O hemograma mostra: Hb 14g/dl, Leucócitos de 5500/mm3 e Plaqueta de 280.000/mm³. Creatinina de 1,0 mg/dL e Cálcio iônico 1,21 mmol/l (Valores de Ref.: 1,17 a 1,32 mmol/l). O médico encaminha-o a um Hematologista, que realiza um mielograma, com o seguinte resultado: medula óssea normocelular, com 8% de plasmócitos (valor normal até 3% de plasmócitos). Um inventário ósseo é então solicitado, com os seguintes achados: RX de tórax, coluna cervical, torácica, lombar, fêmures, bacia, úmeros, crânio, sem sinais de lises ósseas ou fraturas. A principal hipótese diagnóstica, com a respectiva conduta, seria, então:","options":{"A":"Gamopatia de Significado Indeterminado; apenas observar","B":"Mieloma Múltiplo assintomático; quimioterapia","C":"Mieloma Múltiplo; apenas observar, visto que o paciente não apresenta sintomas","D":"Gamopatia de Significado Indeterminado; quimioterapia, pois a doença costuma"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587544","ankiGuid":"NK-QP?Mcij"},{"id":"anki-hematologia-gamopatias-monoclonais-f2b63512fd1dbb5f","number":"1052j","sourceNumber":"1052j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Paciente do sexo masculino, 72 anos, apresentou anemia, lesões ósseas líticas, hipercalcemia e insuficiência renal. Qual é o diagnóstico MAIS provável?","options":{"A":"Leucemia Mielóide Aguda","B":"Mieloma Múltiplo","C":"Leucemia Linfoide Aguda","D":"Mielodisplasia"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587545","ankiGuid":"tZ6e,DlZ<!"},{"id":"anki-hematologia-gamopatias-monoclonais-d9d873ef1805505a","number":"1053j","sourceNumber":"1053j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"A associação de anemia, hipercalcemia, insuficiência renal e fraturas patológicas são características de:","options":{"A":"Deficiência de vitamina D","B":"Mieloma múltiplo","C":"Linfoma de Hodgkin","D":"Carcinoma papilífero da tiróide"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587546","ankiGuid":"t*;>C>UaJ1"},{"id":"anki-hematologia-gamopatias-monoclonais-a275d6902f3e2e88","number":"1054j","sourceNumber":"1054j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Homem de 67 anos está em tratamento de anemia há 10 meses sem melhora. Há 2 meses refere dor lombar persistente com piora progressiva. Foi medicado com anti-inflamatórios em 3 momentos, mas sem melhora efetiva do sintoma. Exames complementares: GV = 3.050.000/mm³; Hb = 10 g/dl; Ht = 30%; VCM = 88 fl; HCM = 32 pg; sem alterações de glóbulos brancos e plaquetas; creatinina: 2,7 mg/dl; ureia: 98 mg/dl; TGO: 45 U/L; TGP: 38 U/L; RX de coluna lombar: osteopenia difusa e fraturas parciais de L3 e L4 por encunhamento. O diagnóstico mais provável e de investigação são, respectivamente:","options":{"A":"Mieloma múltiplo; eletroforese de proteínas séricas e urinárias e avaliação de medula óssea (mielograma e biópsia)","B":"Mieloma múltiplo; proteinúria de Bence-Jones e cintilografia óssea","C":"Anemia ferropriva e insuficiência renal pelo uso de AINH; endoscopia digestiva alta e colonoscopia","D":"Anemia associada à inflamação crônica e à insuficiência renal; perfil do ferro"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587547","ankiGuid":"qNet46?vvA"},{"id":"anki-hematologia-gamopatias-monoclonais-0937303d34db1553","number":"1055j","sourceNumber":"1055j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Uma paciente de 76 anos, assintomática, em exame de rotina realiza uma eletroforese de proteínas plasmáticas que apresenta aumento das taxas de gamaglobulinas do tipo pico monoclonal. Qual das alternativas abaixo NÃO deve constituir uma hipótese diagnóstica?","options":{"A":"Mieloma","B":"Hepatite crônica ativa","C":"Amiloidose primária","D":"Linfoma"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587548","ankiGuid":"LMtv?C)}28"},{"id":"anki-hematologia-gamopatias-monoclonais-4ac78c13034b3df7","number":"1056j","sourceNumber":"1056j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Paciente masculino, 60 anos, interna com queixa de fraqueza generalizada e inapetência. Nega febre, alteração de hábito intestinal ou alergias. Os exames laboratoriais demostraram hemoglobina = 6,2 g/dl e creatinina = 3,5 mg/dl. Dentre outros exames solicitados, avalie o abaixo demonstrado para responder à questão a seguir.\n\nQual o PROVÁVEL diagnóstico?","options":{"A":"Hipoalbuminemia secundária e síndrome nefrótica","B":"Síndrome nefrítica","C":"Anemia hemolítica auto-imune","D":"Anemia megaloblástica","E":"Mieloma múltiplo"},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":["question_bank/media/hematologia-gamopatias-monoclonais/paste-fdeb60cf7b727bdd6a18ab783d03ec790471e3b9.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587549","ankiGuid":"hDlOCWc(Ba"},{"id":"anki-hematologia-gamopatias-monoclonais-f405fafa32b32e5e","number":"1057j","sourceNumber":"1057j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Uma paciente de 70 anos, assintomática, apresenta pico monoclonal de gamaglobulinas em eletroforese de proteínas séricas, que foi solicitada em exame de \"check-up\". Não há nenhum achado digno de nota ao exame clínico bem como nenhuma outra alteração laboratorial. Qual o diagnóstico MAIS PROVÁVEL?","options":{"A":"Gamopatia monoclonal de significado indeterminado","B":"Mieloma múltiplo","C":"Amiloidose","D":"Macroglobulinemia de Waldenström","E":"Linfoma de Hodgkin"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587550","ankiGuid":"e}M#jP5X$U"},{"id":"anki-hematologia-gamopatias-monoclonais-0a11c21a47f98da6","number":"1058j","sourceNumber":"1058j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Em um homem de 70 anos foi detectado em eletroforese de proteínas séricas pico monoclonal ≥ 30 g/L. As dosagens de cálcio e creatinina foram normais. O aspirado de medula óssea revelou plasmócitos clonais ≥ 10%. O diagnóstico é:","options":{"A":"Doença de Paget","B":"Mieloma não secretor","C":"Gamopatia monoclonal de significado indeterminado","D":"Mieloma assintomático (\"smoldering\" mieloma)"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587551","ankiGuid":"xC*HQwGH<n"},{"id":"anki-hematologia-gamopatias-monoclonais-f82241943ab76c7a","number":"1059j","sourceNumber":"1059j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Paciente tabagista de longa data vem evoluindo com dor lombar importante, pior com o movimento. Nos últimos 6 meses apresentou 3 episódios de pneumonia. Durante investigação os exames revelaram anemia (Hto: 25%), diminuição da função renal (creatinina: 1,4), hipercalcemia (cálcio: 11). Diante do exposto acima que outros exames poderiam ajudar a elucidar o diagnóstico:","options":{"A":"Eletroforese de proteínas, Rx de crânio, e aspirado de Medula óssea","B":"Prova de função respiratória, TSH, T4 livre","C":"Hepatograma, ferritina sérica","D":"Ecocardiograma com Doppler, Tomografia computadorizada de tórax"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587552","ankiGuid":"nW.L>CtU2("},{"id":"anki-hematologia-gamopatias-monoclonais-036250d800a4dbe4","number":"1060j","sourceNumber":"1060j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Em casos de Mieloma Múltiplo, é INCORRETO afirmar que:","options":{"A":"Na gênese da lesão renal associada à doença, é essencial o depósito de substância amiloide","B":"Pacientes com MM podem cursar laboratorialmente com pseudo-hiponatremia","C":"Há nítida correlação entre prognóstico e creatinina sérica","D":"Uma das complicações da doença é o desenvolvimento de insuficiência renal","E":"A dor óssea é uma manifestação frequente da doença"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587553","ankiGuid":"Fk{`K5V~x9"},{"id":"anki-hematologia-gamopatias-monoclonais-e0b4bc16fced0af7","number":"1061j","sourceNumber":"1061j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Paciente de 64 anos procura médico, com queixa de dor lombar há 6 meses, com piora súbita hoje, após levantar-se da cadeira, e com dificuldade para permanecer em pé. Refere ainda redução da diurese nos últimos dias, cansaço, náuseas e constipação intestinal. Ao exame, paciente apresenta-se descorado e com redução de força em membros inferiores. RX de coluna lombo-sacra mostrou fratura de L4 e Lesões osteolíticas em bacia. Exames laboratoriais: Creatinina 3,2 mg/dl; Ureia 185 mg/dl; Cálcio total: 14 mg/dl. Sobre esse caso, a principal hipótese diagnóstica é:","options":{"A":"Hiperparatireoidismo primário","B":"Hiperparatireoidismo secundário","C":"Osteoporose","D":"Mieloma múltiplo","E":"Doença de Paget"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587554","ankiGuid":"GAx_D*JKdW"},{"id":"anki-hematologia-gamopatias-monoclonais-329b2761cc7eeb04","number":"1062j","sourceNumber":"1062j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Paciente de 70 anos, sexo masculino, procura atendimento por quadro de dor lombar de forte intensidade, inédita, sem melhora com uso de anti-inflamatórios não esteroidais. Refere fraqueza corporal generalizada e perda de peso. Mostra nos exames laboratoriais hemoglobina de 8 mg/dl com hemácias normocíticas e normocrômicas. Hematoscopia mostra formação em rouleaux das hemácias. Em relação ao caso descrito, assinale a alternativa que apresenta o diagnóstico mais provável para justificar o quadro clínico do paciente.","options":{"A":"Linfoma não-Hodgkin","B":"Leucemia mieloide aguda","C":"Mieloma múltiplo","D":"Anemia por déficit de vitamina"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587555","ankiGuid":"tB:kKo@46Z"},{"id":"anki-hematologia-gamopatias-monoclonais-014bf2260232c76d","number":"1063j","sourceNumber":"1063j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Paciente do sexo masculino, 55 anos de idade, apresenta síndrome nefrótica associada a equimoses periorbitárias, distrofia de unhas e macroglossia. Qual é a principal hipótese diagnóstica?","options":{"A":"Linfoma não Hodgkin","B":"Amiloidose","C":"Linfoma de Burkitt no adulto","D":"Macroglobulinemia de Waldenström","E":"Leucemia mieloide crônica"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587556","ankiGuid":"H]fWMPXh}+"},{"id":"anki-hematologia-gamopatias-monoclonais-4b9d34c0be628d63","number":"1064j","sourceNumber":"1064j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"O mieloma múltiplo representa uma proliferação maligna dos plasmócitos derivados de um único clone. O tumor, os seus produtos e a resposta do hospedeiro ao tumor resultam em várias disfunções orgânicas e sintomas. Marque o sintoma mais comum no mieloma múltiplo:","options":{"A":"Dor óssea","B":"Anemia microcítica","C":"Anemia de doença crônica","D":"Insuficiência renal","E":"Distúrbio de coagulação"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587557","ankiGuid":"HbuEu@R`}%"},{"id":"anki-hematologia-gamopatias-monoclonais-cadb5de483266b3a","number":"1065j","sourceNumber":"1065j","collectionBlock":"anki:hematologia-gamopatias-monoclonais","collectionLabel":"Anki · Gamopatias Monoclonais","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Gamopatias Monoclonais","subtopic":"","stem":"Homem, 58 anos, negro, procedente de Curitiba, é trazido ao pronto-socorro sonolento e confuso. Seu acompanhante relatou que o mesmo vem apresentando emagrecimento e dores ósseas nos últimos meses, além de náuseas e vômitos há 3 dias. Ao exame físico: paciente confuso e hipocorado ++/4+. Pulso: 84 bpm, PA: 130/80 mmHg, com restante do exame físico normal. Hemograma, Hb: 8,0, normocitose e normocromia. Leucócitos: 4500/mm3 (Bt: 2%, Seg: 65%, Eos: 1%, Baso: 0%, Linf: 28%, Mo: 4%). Plaquetas: 120.000/mm3. Presença de Roleaux. Creatinina: 3,5 mg/dl. Eletroforese de proteínas, Albumina: 2,5 mg/dl, α1: 0,2 g/dl, α2: 0,9 g/dl, β: 1,2 g/dl, γ: 2,8 g/dl, com suspeita de paraproteína. Radiografia de tórax com osteoporose difusa em vértebras e arcos costais. Em relação a este caso clínico, qual a hipótese diagnóstica e a investigação a ser proposta?","options":{"A":"Metástase óssea, mapeamento do esqueleto por cintilografia óssea","B":"Osteomielite, hemocultura","C":"Metaplasia mieloide agnogênica, aspirado de medula óssea","D":"Mieloma múltiplo, imunoeletroforese de proteínas","E":"Doença de Hodgkin, pesquisa de células de Reed-Sternberg"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Gamopatias Monoclonais","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Hematologia","Gamopatias Monoclonais","Anki"],"ankiNoteId":"1742516587558","ankiGuid":"HN{`#nx=4b"}]};
